  1	//! The `.fjgraphic` package (spec §11 G-46 (c)): the package spec's parse and
  2	//! checks, the in-package name legaliser, `manifest.json`, the stored zip
  3	//! with its CRC-32, and the file write. The app hands in the module's and
  4	//! the files' bytes and their project-relative paths; which fonts and assets
  5	//! belong in a package is decided before this module is reached.
  6	//!
  7	//! **The archive** is a stored zip (method 0), version needed 10, made-by
  8	//! `0x031E`, flag bit 11 (UTF-8 names), DOS time 0 and date `0x0021`
  9	//! (1980-01-01) so two writes of one package are byte-identical, no extra
 10	//! fields and no directory entries, external attributes `0o100644 << 16`:
 11	//! `manifest.json` first, then the files in the order given, then the central
 12	//! directory and the end record. There is no Zip64, so an archive over
 13	//! `u32::MAX` bytes (or of more than 65,535 entries) is refused.
 14	//!
 15	//! **An in-package name** `<n>` under `fonts/` or `assets/` is legal when it
 16	//! is non-empty, at most 255 bytes, does not begin with `.`, and holds no
 17	//! `/`, `\`, `:` or control scalar (U+0000–U+001F, U+007F–U+009F). Per
 18	//! folder, the legal names are claimed first in the order given; then each
 19	//! illegal one, in order, has each run of `\`, `:` or control scalars made
 20	//! one `-` and its leading `.`s dropped (empty is `file`), and a name already
 21	//! claimed takes `-2`, `-3`, … before its last `.` (G-23 (c)'s form), the
 22	//! stem cut by whole scalars to stay within 255 bytes. The manifest's `name`
 23	//! keeps the project's own name.
 24	
 25	use std::collections::HashSet;
 26	
 27	use serde_json::{json, Map, Value};
 28	use sha2::{Digest, Sha256};
 29	
 30	use crate::model_graphic::check_name;
 31	
 32	/// The longest in-package name, in UTF-8 bytes (APFS's file-name limit).
 33	const MAX_NAME: usize = 255;
 34	const MANIFEST: &str = "manifest.json";
 35	/// A local header's fixed part, and a central directory entry's.
 36	const LOCAL_FIXED: usize = 30;
 37	const CENTRAL_FIXED: usize = 46;
 38	const END_RECORD: usize = 22;
 39	/// 1980-01-01 as a DOS date: day 1, month 1, year 0.
 40	const DOS_DATE: u16 = 0x0021;
 41	/// Bit 11: the names are UTF-8.
 42	const UTF8_FLAG: u16 = 0x0800;
 43	/// Unix (3) and spec version 3.0 (30), the high and low bytes.
 44	const MADE_BY: u16 = 0x031E;
 45	/// A regular file, `rw-r--r--`, in the external attributes' high half.
 46	const EXTERNAL: u32 = 0o100644 << 16;
 47	
 48	/// One file of the package: its project-relative path, its in-package path,
 49	/// its name in its project folder, and its bytes.
 50	struct Entry<'a> {
 51	    path: String,
 52	    name: String,
 53	    bytes: &'a [u8],
 54	}
 55	
 56	/// Checks `package_json` against `data`, writes the archive at `path`
 57	/// (created or truncated) and answers the `manifest.json` it holds. Every
 58	/// refusal names the value; an input refusal writes nothing.
 59	pub(crate) fn write(path: &str, package_json: &str, data: &[u8]) -> Result<String, String> {
 60	    let archive = build(package_json, data)?;
 61	    std::fs::write(path, &archive.1).map_err(|e| format!("cannot write {path}: {e}"))?;
 62	    Ok(archive.0)
 63	}
 64	
 65	/// The manifest's text and the archive's bytes.
 66	fn build(package_json: &str, data: &[u8]) -> Result<(String, Vec<u8>), String> {
 67	    let spec: Value =
 68	        serde_json::from_str(package_json).map_err(|e| format!("package_json is not JSON: {e}"))?;
 69	    let Some(spec) = spec.as_object() else {
 70	        return Err(format!("package_json must be an object, not {spec}"));
 71	    };
 72	    let module = match spec.get("module") {
 73	        Some(Value::String(module)) => module.clone(),
 74	        other => return Err(format!("module must be a string, not {}", shown(other))),
 75	    };
 76	    check_name(&module)?;
 77	    let title = string(spec, "title")?;
 78	    let category = string(spec, "category")?;
 79	    let app_version = string(spec, "app_version")?;
 80	    let description = match spec.get("description") {
 81	        Some(Value::String(text)) => Value::String(text.clone()),
 82	        Some(Value::Null) => Value::Null,
 83	        other => {
 84	            return Err(format!(
 85	                "description must be a string or null, not {}",
 86	                shown(other)
 87	            ))
 88	        }
 89	    };
 90	    let files = parse_files(spec, &module)?;
 91	    let total = files
 92	        .iter()
 93	        .try_fold(0u64, |sum, (_, size)| sum.checked_add(*size))
 94	        .ok_or_else(|| "the files' sizes overflow".to_string())?;
 95	    if total != data.len() as u64 {
 96	        return Err(format!(
 97	            "the files' sizes sum to {total} bytes, but data holds {}",
 98	            data.len()
 99	        ));
100	    }
101	    let names = package_names(&files);
102	    let mut entries = Vec::with_capacity(files.len());
103	    let mut at = 0usize;
104	    for ((given, size), path) in files.iter().zip(names) {
105	        let end = at + *size as usize;
106	        let name = given.rsplit('/').next().unwrap_or(given).to_string();
107	        entries.push(Entry {
108	            path,
109	            name,
110	            bytes: &data[at..end],
111	        });
112	        at = end;
113	    }
114	    let listed: Vec<Value> = entries
115	        .iter()
116	        .map(|entry| {
117	            json!({
118	                "path": entry.path,
119	                "name": entry.name,
120	                "size": entry.bytes.len(),
121	                "sha256": hex(&Sha256::digest(entry.bytes)),
122	            })
123	        })
124	        .collect();
125	    let mut manifest = Map::new();
126	    manifest.insert("fjgraphic".to_string(), Value::from(1));
127	    manifest.insert("module".to_string(), Value::String(module));
128	    manifest.insert("title".to_string(), Value::String(title));
129	    manifest.insert("category".to_string(), Value::String(category));
130	    manifest.insert("description".to_string(), description);
131	    manifest.insert("app_version".to_string(), Value::String(app_version));
132	    manifest.insert("files".to_string(), Value::Array(listed));
133	    let mut text = serde_json::to_string_pretty(&Value::Object(manifest))
134	        .map_err(|e| format!("the manifest could not be written: {e}"))?;
135	    text.push('\n');
136	    let mut all = vec![(MANIFEST.to_string(), text.as_bytes())];
137	    all.extend(
138	        entries
139	            .iter()
140	            .map(|entry| (entry.path.clone(), entry.bytes)),
141	    );
142	    let archive = zip(&all)?;
143	    Ok((text, archive))
144	}
145	
146	/// A value as a refusal names it; a missing key is `nothing`.
147	fn shown(value: Option<&Value>) -> String {
148	    value.map_or_else(|| "nothing".to_string(), Value::to_string)
149	}
150	
151	fn string(spec: &Map<String, Value>, key: &str) -> Result<String, String> {
152	    match spec.get(key) {
153	        Some(Value::String(text)) => Ok(text.clone()),
154	        other => Err(format!("{key} must be a string, not {}", shown(other))),
155	    }
156	}
157	
158	/// `files` as `(path, size)` pairs: the first exactly `<module>.js`, every
159	/// other `fonts/<n>` or `assets/<n>`, no path twice.
160	fn parse_files(spec: &Map<String, Value>, module: &str) -> Result<Vec<(String, u64)>, String> {
161	    let Some(Value::Array(list)) = spec.get("files") else {
162	        return Err(format!(
163	            "files must be an array, not {}",
164	            shown(spec.get("files"))
165	        ));
166	    };
167	    let mut files = Vec::with_capacity(list.len());
168	    let mut seen = HashSet::new();
169	    for (index, file) in list.iter().enumerate() {
170	        let path = match file.get("path") {
171	            Some(Value::String(path)) => path.clone(),
172	            other => {
173	                return Err(format!(
174	                    "files[{index}].path must be a string, not {}",
175	                    shown(other)
176	                ))
177	            }
178	        };
179	        let Some(size) = file.get("size").and_then(Value::as_u64) else {
180	            return Err(format!(
181	                "files[{index}].size must be a whole number of bytes, not {}",
182	                shown(file.get("size"))
183	            ));
184	        };
185	        let module_file = format!("{module}.js");
186	        if index == 0 {
187	            if path != module_file {
188	                return Err(format!(
189	                    "the first file must be \"{module_file}\", not \"{path}\""
190	                ));
191	            }
192	        } else if !in_folder(&path) {
193	            return Err(format!(
194	                "file \"{path}\" is not fonts/<name> or assets/<name> (a name of 1 to 255 bytes with no /)"
195	            ));
196	        }
197	        if !seen.insert(path.clone()) {
198	            return Err(format!("file \"{path}\" is given twice"));
199	        }
200	        files.push((path, size));
201	    }
202	    if files.is_empty() {
203	        return Err(format!(
204	            "files must begin with \"{module}.js\", not be empty"
205	        ));
206	    }
207	    Ok(files)
208	}
209	
210	/// `fonts/<n>` or `assets/<n>`, `<n>` non-empty, at most 255 bytes, no `/`.
211	fn in_folder(path: &str) -> bool {
212	    let name = path
213	        .strip_prefix("fonts/")
214	        .or_else(|| path.strip_prefix("assets/"));
215	    name.is_some_and(|n| !n.is_empty() && n.len() <= MAX_NAME && !n.contains('/'))
216	}
217	
218	/// U+0000–U+001F and U+007F–U+009F.
219	fn is_control(c: char) -> bool {
220	    matches!(c as u32, 0..=0x1F | 0x7F..=0x9F)
221	}
222	
223	/// What the legaliser replaces: `\`, `:` and the control scalars.
224	fn is_replaced(c: char) -> bool {
225	    c == '\\' || c == ':' || is_control(c)
226	}
227	
228	fn is_legal(name: &str) -> bool {
229	    !name.is_empty()
230	        && name.len() <= MAX_NAME
231	        && !name.starts_with('.')
232	        && !name.chars().any(|c| c == '/' || is_replaced(c))
233	}
234	
235	/// Each run of replaced scalars one `-`, leading `.`s dropped, empty `file`.
236	fn legalise(name: &str) -> String {
237	    let mut out = String::with_capacity(name.len());
238	    let mut in_run = false;
239	    for c in name.chars() {
240	        if is_replaced(c) {
241	            if !in_run {
242	                out.push('-');
243	            }
244	            in_run = true;
245	        } else {
246	            out.push(c);
247	            in_run = false;
248	        }
249	    }
250	    let kept = out.trim_start_matches('.');
251	    if kept.is_empty() {
252	        "file".to_string()
253	    } else {
254	        kept.to_string()
255	    }
256	}
257	
258	/// `name` with `-<k>` before its last `.`, the stem (then, only if it must,
259	/// the extension) cut by whole scalars to stay within 255 bytes.
260	fn suffixed(name: &str, k: usize) -> String {
261	    let (mut stem, mut ext) = match name.rfind('.') {
262	        Some(dot) if dot > 0 => (name[..dot].to_string(), name[dot..].to_string()),
263	        _ => (name.to_string(), String::new()),
264	    };
265	    let tag = format!("-{k}");
266	    while stem.len() + tag.len() + ext.len() > MAX_NAME {
267	        if stem.pop().is_none() && ext.pop().is_none() {
268	            break;
269	        }
270	    }
271	    format!("{stem}{tag}{ext}")
272	}
273	
274	/// Each file's in-package path: the module's as given; per folder, the legal
275	/// names claimed first, then each illegal one legalised and suffixed free.
276	fn package_names(files: &[(String, u64)]) -> Vec<String> {
277	    let mut out: Vec<Option<String>> = vec![None; files.len()];
278	    out[0] = Some(files[0].0.clone());
279	    for folder in ["fonts/", "assets/"] {
280	        let mine: Vec<(usize, &str)> = files
281	            .iter()
282	            .enumerate()
283	            .skip(1)
284	            .filter_map(|(i, (path, _))| path.strip_prefix(folder).map(|n| (i, n)))
285	            .collect();
286	        let mut claimed: HashSet<String> = HashSet::new();
287	        for &(i, name) in &mine {
288	            if is_legal(name) {
289	                claimed.insert(name.to_string());
290	                out[i] = Some(format!("{folder}{name}"));
291	            }
292	        }
293	        for &(i, name) in &mine {
294	            if is_legal(name) {
295	                continue;
296	            }
297	            let base = legalise(name);
298	            let mut chosen = base.clone();
299	            let mut k = 2;
300	            while claimed.contains(&chosen) {
301	                chosen = suffixed(&base, k);
302	                k += 1;
303	            }
304	            claimed.insert(chosen.clone());
305	            out[i] = Some(format!("{folder}{chosen}"));
306	        }
307	    }
308	    out.into_iter().map(Option::unwrap_or_default).collect()
309	}
310	
311	fn hex(bytes: &[u8]) -> String {
312	    bytes.iter().map(|b| format!("{b:02x}")).collect()
313	}
314	
315	/// CRC-32 (IEEE): the reflected polynomial `0xEDB88320`, init and xorout
316	/// `0xFFFFFFFF`, by a 256-entry table.
317	fn crc32(bytes: &[u8]) -> u32 {
318	    let mut table = [0u32; 256];
319	    for (n, slot) in table.iter_mut().enumerate() {
320	        let mut c = n as u32;
321	        for _ in 0..8 {
322	            c = if c & 1 != 0 {
323	                0xEDB8_8320 ^ (c >> 1)
324	            } else {
325	                c >> 1
326	            };
327	        }
328	        *slot = c;
329	    }
330	    let mut crc = 0xFFFF_FFFFu32;
331	    for &b in bytes {
332	        crc = table[((crc ^ u32::from(b)) & 0xFF) as usize] ^ (crc >> 8);
333	    }
334	    crc ^ 0xFFFF_FFFF
335	}
336	
337	/// The stored zip of `entries`, in order; refused past what a zip without
338	/// Zip64 can hold.
339	fn zip(entries: &[(String, &[u8])]) -> Result<Vec<u8>, String> {
340	    let mut size: u64 = END_RECORD as u64;
341	    for (name, bytes) in entries {
342	        size += (LOCAL_FIXED + CENTRAL_FIXED + 2 * name.len() + bytes.len()) as u64;
343	    }
344	    if size > u64::from(u32::MAX) || entries.len() > usize::from(u16::MAX) {
345	        return Err(format!(
346	            "the package would be {size} bytes in {} entries, more than a zip without Zip64 holds ({} bytes, {} entries)",
347	            entries.len(),
348	            u32::MAX,
349	            u16::MAX
350	        ));
351	    }
352	    let mut out = Vec::with_capacity(size as usize);
353	    let mut central = Vec::new();
354	    for (name, bytes) in entries {
355	        let offset = out.len() as u32;
356	        let crc = crc32(bytes);
357	        let len = bytes.len() as u32;
358	        let name_len = name.len() as u16;
359	        put32(&mut out, 0x0403_4b50);
360	        for field in [10, UTF8_FLAG, 0, 0, DOS_DATE] {
361	            put16(&mut out, field);
362	        }
363	        for field in [crc, len, len] {
364	            put32(&mut out, field);
365	        }
366	        put16(&mut out, name_len);
367	        put16(&mut out, 0);
368	        out.extend_from_slice(name.as_bytes());
369	        out.extend_from_slice(bytes);
370	
371	        put32(&mut central, 0x0201_4b50);
372	        for field in [MADE_BY, 10, UTF8_FLAG, 0, 0, DOS_DATE] {
373	            put16(&mut central, field);
374	        }
375	        for field in [crc, len, len] {
376	            put32(&mut central, field);
377	        }
378	        for field in [name_len, 0, 0, 0, 0] {
379	            put16(&mut central, field);
380	        }
381	        put32(&mut central, EXTERNAL);
382	        put32(&mut central, offset);
383	        central.extend_from_slice(name.as_bytes());
384	    }
385	    let central_at = out.len() as u32;
386	    let central_len = central.len() as u32;
387	    out.extend_from_slice(&central);
388	    let count = entries.len() as u16;
389	    put32(&mut out, 0x0605_4b50);
390	    for field in [0, 0, count, count] {
391	        put16(&mut out, field);
392	    }
393	    put32(&mut out, central_len);
394	    put32(&mut out, central_at);
395	    put16(&mut out, 0);
396	    Ok(out)
397	}
398	
399	fn put16(out: &mut Vec<u8>, value: u16) {
400	    out.extend_from_slice(&value.to_le_bytes());
401	}
402	
403	fn put32(out: &mut Vec<u8>, value: u32) {
404	    out.extend_from_slice(&value.to_le_bytes());
405	}

