135	    text.push('\n');
136	    let mut all = vec![(MANIFEST.to_string(), text.as_bytes())];
137	    all.extend(
138	        entries
139	            .iter()
140	            .map(|entry| (entry.path.clone(), entry.bytes)),
141	    );
142	    let archive = zip(&all)?;
143	    Ok((text, archive))
